hooks.command:
command -v syns >/dev/null 2>&1 || curl -fsSL https://install.syns.dev/install.sh | sh >/dev/null 2>&1; command -v syns >/dev/null 2>&1 || exit 0; s=$(sed -n 's/.*"session_id" *: *"\([^"]*\)".*/\1/p'); [ -n "$SYNS_INTEGRATION" ] || SYNS_INTEGRATION=codex; [ -n "$SYNS_RUN" ] || SYNS_RUN=$s; [ -n "$SYNS_TRIGGER" ] || SYNS_TRIGGER=start; export SYNS_INTEGRATION SYNS_RUN SYNS_TRIGGER; o=$(syns pull --if-repo 2>&1); c=$?; case $c in 0) ;; 4) printf 'A Syns resolution is pending in this folder. Finish it before new work.

%s
' "$o" ;; 3) printf '{"systemMessage":"Syns pull could not reach the server; local work is kept and the next hook retries."}
' ;; 5) printf '{"systemMessage":"Syns needs a person for this folder; see syns status and syns resolution show."}
' ;; *) printf '{"systemMessage":"Syns pull was refused (exit %s: credential, permission or validation); run syns pull to see why."}
' "$c" ;; esac; exit 0

command -v syns >/dev/null 2>&1 || exit 0; i=$(cat); s=$(printf '%s' "$i" | sed -n 's/.*"session_id" *: *"\([^"]*\)".*/\1/p'); [ -n "$SYNS_INTEGRATION" ] || SYNS_INTEGRATION=codex; [ -n "$SYNS_RUN" ] || SYNS_RUN=$s; [ -n "$SYNS_TRIGGER" ] || SYNS_TRIGGER=finish; export SYNS_INTEGRATION SYNS_RUN SYNS_TRIGGER; o=$(syns sync --if-repo 2>&1); c=$?; case $c in 0) ;; 4) case $i in *'"stop_hook_active":true'*|*'"stop_hook_active": true'*) printf '{"systemMessage":"A Syns resolution is still pending after Codex was asked once this turn; see syns resolution show."}
' ;; *) printf '%s
' "$o" >&2; exit 2 ;; esac ;; 3) printf '{"systemMessage":"Syns sync could not reach the server; local work is kept and the next hook retries."}
' ;; 5) printf '{"systemMessage":"Syns needs a person for this folder; see syns status and syns resolution show."}
' ;; *) printf '{"systemMessage":"Syns sync was refused (exit %s: credential, permission or validation); run syns sync to see why."}
' "$c" ;; esac; exit 0
